PRAGMA foreign_keys=OFF;
BEGIN;
PRAGMA writable_schema = on;
CREATE TABLE IF NOT EXISTS  system_info(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS  samples(
          id INTEGER PRIMARY KEY,asset_tag TEXT NOT NULL,seq_no INTEGER NOT NULL,
          device_time_ns INTEGER NOT NULL,gateway_time_ns INTEGER NOT NULL,
          sensor_value REAL NOT NULL,quality INTEGER NOT NULL,UNIQUE(asset_tag,seq_no));
CREATE TABLE IF NOT EXISTS  runtime_events(id INTEGER PRIMARY KEY,event_time_ns INTEGER,lane INTEGER,code TEXT,detail TEXT);
CREATE TABLE IF NOT EXISTS  analyst_queue(id INTEGER PRIMARY KEY,source TEXT,untrusted_content TEXT);
